import { l, type L, type Class9Chapter, type ChoiceTask, type SelectTask, type MatchTask, type OrderTask, type NumberTask } from './types';

const base = (prompt: L, context: L) => ({
  prompt, context,
  success: l('Your record fits the supplied case. Explain the evidence and any fact that is still unknown.', 'आपका रिकॉर्ड दिए मामले से मेल खाता है। प्रमाण और जो बात अभी अज्ञात है, उसे समझाएँ।'),
  correction: l('Use the specific reasons below to revise your record. Check the supplied evidence before trying again.', 'नीचे दिए खास कारणों से रिकॉर्ड सुधारें। फिर कोशिश करने से पहले दिए प्रमाण जाँचें।'),
  hint: l('Separate the claim from the record. Check what action is requested and ask a trusted adult through a known route.', 'दावे और रिकॉर्ड को अलग करें। माँगी गई कार्रवाई जाँचें और ज्ञात रास्ते से विश्वसनीय बड़े की मदद लें।'),
});
type AnswerOption = [string, L, L];
const choice = (p: L, c: L, options: AnswerOption[], correct: string): ChoiceTask => ({ ...base(p, c), kind: 'choice', options: options.map(([id, label, feedback]) => ({ id, label, feedback })), correct });
const select = (p: L, c: L, items: AnswerOption[], expected: string[]): SelectTask => ({ ...base(p, c), kind: 'select', items: items.map(([id, label, feedback]) => ({ id, label, feedback })), expected });
const match = (p: L, c: L, rows: [string, L, string, L][], options: [string, L][]): MatchTask => ({ ...base(p, c), kind: 'match', rows: rows.map(([id, label, answer, explanation]) => ({ id, label, answer, explanation })), options: options.map(([id, label]) => ({ id, label })) });
const order = (p: L, c: L, steps: [string, L, L][]): OrderTask => ({ ...base(p, c), kind: 'order', items: steps.map(([id, label]) => ({ id, label })), expected: steps.map(([id]) => id), stepReasons: steps.map(([, , reason]) => reason) });
const number = (p: L, c: L, fields: [string, L, number, L][]): NumberTask => ({ ...base(p, c), kind: 'number', fields: fields.map(([id, label, answer, explanation]) => ({ id, label, answer, min: 0, explanation })) });
const scene = (title: L, caption: L, dialogue: L) => ({ title, caption, dialogue });
